/// Spacing, sizes, radii, layout and type sizes, in points.
public enum RDimension {
    /// The smallest legible label.
    public static let fontSizeXs: CGFloat = 11
    /// Default label size.
    public static let fontSizeSm: CGFloat = 12
    /// Button labels and supporting text.
    public static let fontSizeMd: CGFloat = 14
    /// Body text.
    public static let fontSizeBase: CGFloat = 16
    /// Large body.
    public static let fontSizeLg: CGFloat = 18
    /// Quotes and small display.
    public static let fontSizeXl: CGFloat = 22
    /// Big numbers.
    public static let fontSize2xl: CGFloat = 28
    /// Screen headline (display).
    public static let fontSize3xl: CGFloat = 30
    /// Hero display moment.
    public static let fontSize4xl: CGFloat = 40
    /// Reading and controls text: iOS body size.
    public static let fontSizeBody: CGFloat = 17
    /// Page and episode titles, splash lines.
    public static let fontSizeTitle: CGFloat = 34
    /// One hero word or line per screen at most.
    public static let fontSizeHero: CGFloat = 64
    /// 0pt step.
    public static let space0: CGFloat = 0
    /// 4pt step.
    public static let space1: CGFloat = 4
    /// 8pt step.
    public static let space2: CGFloat = 8
    /// 12pt step.
    public static let space3: CGFloat = 12
    /// 16pt step.
    public static let space4: CGFloat = 16
    /// 20pt step.
    public static let space5: CGFloat = 20
    /// 24pt step.
    public static let space6: CGFloat = 24
    /// 32pt step.
    public static let space8: CGFloat = 32
    /// 40pt step.
    public static let space10: CGFloat = 40
    /// 48pt step.
    public static let space12: CGFloat = 48
    /// 64pt step.
    public static let space16: CGFloat = 64
    /// Left and right page margin.
    public static let spaceScreenMargin: CGFloat = 24
    /// Between sections of a screen.
    public static let spaceSection: CGFloat = 32
    /// Between items in a list (space instead of dividers).
    public static let spaceRowGap: CGFloat = 24
    /// Between a title and its label.
    public static let spaceStackTight: CGFloat = 8
    /// Between related blocks.
    public static let spaceStackDefault: CGFloat = 16
    /// Between side-by-side items (paywall buttons: 13).
    public static let spaceInline: CGFloat = 12
    /// Inside a pill, left and right.
    public static let spaceControlPadding: CGFloat = 20
    /// Left inset of list content and dividers.
    public static let spaceListInset: CGFloat = 16
    /// Space between journal entries.
    public static let spaceBetweenEntries: CGFloat = 24
    /// Chips and small icon buttons.
    public static let sizeControlSmall: CGFloat = 32
    /// Ordinary buttons (Apple minimum touch target).
    public static let sizeControlDefault: CGFloat = 44
    /// Prominent buttons.
    public static let sizeControlLarge: CGFloat = 48
    /// The paywall-scale primary and secondary.
    public static let sizeControlHero: CGFloat = 60
    /// Nothing tappable is smaller than this.
    public static let sizeTouchTarget: CGFloat = 44
    /// Inline icons.
    public static let sizeIconSmall: CGFloat = 16
    /// Standard icons.
    public static let sizeIconDefault: CGFloat = 20
    /// Transport and primary icons.
    public static let sizeIconLarge: CGFloat = 24
    /// Artwork in a list row.
    public static let sizeArtworkRow: CGFloat = 40
    /// Artwork in a card or on the player header.
    public static let sizeArtworkCard: CGFloat = 64
    /// A show or episode page.
    public static let sizeArtworkPlayer: CGFloat = 120
    /// A full-bleed moment.
    public static let sizeArtworkHero: CGFloat = 240
    /// The Retrospect mark disc.
    public static let sizeMark: CGFloat = 38
    /// Height of the mini-player.
    public static let sizeMiniPlayer: CGFloat = 42
    /// Thickness of progress and scrubber tracks.
    public static let sizeProgress: CGFloat = 3
    /// Hairline edges.
    public static let sizeBorderHairline: CGFloat = 0.5
    /// Rims and outlines.
    public static let sizeBorderDefault: CGFloat = 1
    /// Outer rings and focus.
    public static let sizeBorderRing: CGFloat = 2
    /// The thick inner stroke on the input card.
    public static let sizeBorderInset: CGFloat = 4
    /// A person in a list or a message.
    public static let sizeAvatarSmall: CGFloat = 28
    /// A person in a row.
    public static let sizeAvatarDefault: CGFloat = 40
    /// A person at the top of their page.
    public static let sizeAvatarLarge: CGFloat = 72
    /// Height of a count or status badge.
    public static let sizeBadge: CGFloat = 20
    /// Inline padding of a tag (Paper label · today: 20 tall, radius 10, padding 7). The guess dot side takes 6.
    public static let sizeTagPadding: CGFloat = 7
