/// Springs and curves from motion.* (design-system/principles/motion-system.md). Views use these, never a raw .spring(...).
public enum RMotion {
    /// Nodes settling after a drag or a zoom.
    public static let map: Animation = .spring(response: 0.45, dampingFraction: 0.8)
    /// A sheet arriving or being dragged.
    public static let sheet: Animation = .spring(response: 0.4, dampingFraction: 0.86)
    /// A sheet leaving after a flick or a drag past the threshold.
    public static let sheetDismiss: Animation = .spring(response: 0.32, dampingFraction: 0.9)
    /// A menu growing out of the thing you tapped: settles in about 230ms with a slight overshoot (about 3%).
    public static let popover: Animation = .spring(response: 0.3, dampingFraction: 0.74)
    /// Firm and immediate, ~1% overshoot: press release, toggles, segmented thumb, checkmarks, tab icon.
    public static let snappy: Animation = .spring(response: 0.25, dampingFraction: 0.82)
    /// Dragged through water, ~5% overshoot: tiles lagging the scroll, off-axis cards settling on appear.
    public static let settle: Animation = .spring(response: 0.45, dampingFraction: 0.7)
    /// Delight, ~10% overshoot, used rarely: knows-you-well, a goal met, first episode ready, badges.
    public static let pop: Animation = .spring(response: 0.35, dampingFraction: 0.6)
    /// Big and calm, no overshoot: large layout changes, the page behind a sheet.
    public static let gentle: Animation = .spring(response: 0.55, dampingFraction: 0.92)
    /// Things arriving.
    public static func standard(_ duration: Double) -> Animation { .timingCurve(0.16, 1, 0.3, 1, duration: duration) }
    /// Things leaving.
    public static func exit(_ duration: Double) -> Animation { .timingCurve(0.4, 0, 1, 1, duration: duration) }
    /// Symmetric in-out for non-gesture moves that start and end at rest (meter fill, progress steps).
    public static func move(_ duration: Double) -> Animation { .timingCurve(0.65, 0, 0.35, 1, duration: duration) }
}

/// Haptics from haptic.* as SwiftUI feedback. Pair each with the visual change it lands on.
public enum RHaptic {
    /// Choosing between options.
    public static let select: SensoryFeedback = .selection
    /// Something saved or done.
    public static let confirm: SensoryFeedback = .success
    /// The first-insight moment.
    public static let reveal: SensoryFeedback = .impact(flexibility: .soft)
    /// Something needs attention.
    public static let warning: SensoryFeedback = .warning
    /// The app starts listening.
    public static let listenStart: SensoryFeedback = .impact(weight: .light)
    /// The app stops listening.
    public static let listenStop: SensoryFeedback = .impact(weight: .medium)
    /// The app hands the turn back to you.
    public static let turn: SensoryFeedback = .selection
    /// Something failed.
    public static let error: SensoryFeedback = .error
    /// Switching tabs.
    public static let tab: SensoryFeedback = .selection
    /// Recording starts.
    public static let recordStart: SensoryFeedback = .impact(weight: .medium)
    /// Recording stops.
    public static let recordStop: SensoryFeedback = .impact(weight: .light)
    /// Pull to refresh lets go.
    public static let refresh: SensoryFeedback = .impact(weight: .light)
    /// A long press opens a menu.
    public static let longPress: SensoryFeedback = .impact(weight: .medium)
    /// A primary or destructive action pressed (once, on touch down).
    public static let press: SensoryFeedback = .impact(weight: .light)
    /// Scrubbing across a chapter boundary.
    public static let chapterTick: SensoryFeedback = .selection
    /// A sheet settling at a resting height after a drag.
    public static let sheetSnap: SensoryFeedback = .impact(flexibility: .soft)
    /// Skip back 15 or forward 30.
    public static let skip: SensoryFeedback = .impact(weight: .light)
    /// Retro typing out an onboarding question: one faint tick per word (not per letter), at most ~10 a second, silent on spaces and punctuation; stops when the person starts talking. Founder, 21 Oct.
    public static let typeOn: SensoryFeedback = .impact(flexibility: .soft, intensity: 0.35)
}

